import ipaddress
def effective_route(tables,vpc,subnet,destination):
    address=ipaddress.IPv4Address(destination)
    candidates=[table for table in tables if table['vpc_id']==vpc]
    explicit=[table for table in candidates if subnet in table['subnets']]
    selected=explicit if explicit else [table for table in candidates if table['main']]
    if len(selected)!=1:raise ValueError('ambiguous or absent subnet route-table association')
    table=selected[0];routes=[];seen=set()
    for route in table['routes']:
        network=ipaddress.IPv4Network(route['cidr'],strict=True)
        if network in seen or route['state'] not in ('active','blackhole'):raise ValueError('unsupported or ambiguous static route')
        seen.add(network)
        if address in network:routes.append((network.prefixlen,route))
    if not routes:return {'table':table['id'],'route':None}
    chosen=max(routes,key=lambda item:item[0])[1]
    return {'table':table['id'],'route':dict(chosen)}
```

