def wait_operation(fetch,self_link,max_polls):
    if type(max_polls) is not int or not 1<=max_polls<=20:raise ValueError('bounded poll count')
    for _ in range(max_polls):
        row=fetch(self_link)
        if row.get('selfLink')!=self_link or row.get('status') not in ('PENDING','RUNNING','DONE'):raise ValueError('wrong operation or status')
        if row['status']=='DONE':
            if 'error' in row or row.get('httpErrorStatusCode',0)>=400:raise RuntimeError('operation completed with error')
            if not isinstance(row.get('targetLink'),str) or not row['targetLink']:raise ValueError('missing created target')
            return {'name':row['name'],'targetLink':row['targetLink']}
    raise TimeoutError('operation still pending; outcome not declared failed')
```

